"use client";

import * as React from "react";
import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { buttonVariants } from "@/components/ui/button";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Margin Dialog root: owns the open state of one modal window. */
const Dialog = DialogPrimitive.Root;

/** The control that opens the dialog. */
const DialogTrigger = DialogPrimitive.Trigger;

/** Moves the dialog to the end of the document body. */
const DialogPortal = DialogPrimitive.Portal;

/** Closes the dialog; wrap a Cancel or Done button in it. */
const DialogClose = DialogPrimitive.Close;

/** Margin dialog scrim: a soft grey veil that fades in. */
const DialogOverlay = React.forwardRef<HTMLDivElement, WithClassName<DialogPrimitive.Backdrop.Props>>(
  ({ className, ...props }, ref) => (
    <DialogPrimitive.Backdrop
      ref={ref}
      data-slot="dialog-overlay"
      className={cn(
        "fixed inset-0 z-50 bg-(--scrim)",
        "transition-opacity duration-base ease-(--ease-out)",
        "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
        className,
      )}
      {...props}
    />
  ),
);
DialogOverlay.displayName = "DialogOverlay";

/**
 * Margin dialog window: a white panel with the large corner and a long soft
 * drop. It grows in a little as it fades, and a ghost button closes it.
 */
const DialogContent = React.forwardRef<HTMLDivElement, WithClassName<DialogPrimitive.Popup.Props>>(
  ({ className, children, ...props }, ref) => (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Popup
        ref={ref}
        data-slot="dialog-content"
        className={cn(
          "fixed inset-x-4 top-1/2 z-50 mx-auto grid max-w-lg -translate-y-1/2 gap-4",
          "rounded-3xl bg-popover p-5 text-popover-foreground shadow-(--shadow-overlay) outline-none",
          "transition-[opacity,scale] duration-base ease-(--ease-out)",
          "data-[starting-style]:scale-97 data-[starting-style]:opacity-0",
          "data-[ending-style]:scale-97 data-[ending-style]:opacity-0",
          className,
        )}
        {...props}
      >
        {children}
        <DialogPrimitive.Close
          data-slot="dialog-close"
          className={cn(buttonVariants({ variant: "ghost", size: "icon-sm" }), "absolute end-3 top-3")}
        >
          <Icon icon="solar:close-circle-linear" className="size-4" aria-hidden="true" />
          <span className="sr-only">Close</span>
        </DialogPrimitive.Close>
      </DialogPrimitive.Popup>
    </DialogPortal>
  ),
);
DialogContent.displayName = "DialogContent";

/** The title block at the top of a dialog, leaving room for the close button. */
const DialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="dialog-header"
    className={cn("flex flex-col gap-1 pe-8 text-start", className)}
    {...props}
  />
);
DialogHeader.displayName = "DialogHeader";

/** The action row: stacked on a phone, in a row at the end from the small breakpoint. */
const DialogFooter = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="dialog-footer"
    className={cn("flex flex-col-reverse gap-2 sm:flex-row sm:justify-end", className)}
    {...props}
  />
);
DialogFooter.displayName = "DialogFooter";

/** The dialog title in semibold. */
const DialogTitle = React.forwardRef<HTMLHeadingElement, WithClassName<DialogPrimitive.Title.Props>>(
  ({ className, ...props }, ref) => (
    <DialogPrimitive.Title
      ref={ref}
      data-slot="dialog-title"
      className={cn("text-base font-semibold leading-snug text-foreground", className)}
      {...props}
    />
  ),
);
DialogTitle.displayName = "DialogTitle";

/** The supporting line under the title, in muted grey. */
const DialogDescription = React.forwardRef<
  HTMLParagraphElement,
  WithClassName<DialogPrimitive.Description.Props>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description
    ref={ref}
    data-slot="dialog-description"
    className={cn("text-sm leading-relaxed text-muted-foreground", className)}
    {...props}
  />
));
DialogDescription.displayName = "DialogDescription";

export {
  Dialog,
  DialogPortal,
  DialogOverlay,
  DialogClose,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogFooter,
  DialogTitle,
  DialogDescription,
};
